function accId(): string { return bin2hex(random_bytes(16)); }
function accValidDate(string $value): bool { $date=DateTimeImmutable::createFromFormat('!Y-m-d',$value); return $date instanceof DateTimeImmutable && $date->format('Y-m-d')===$value; }
function accValidPeriod(string $value): bool { return preg_match('/^\d{4}$/',$value)===1||preg_match('/^\d{4}-(0[1-9]|1[0-2])$/',$value)===1||preg_match('/^\d{4}-Q[1-4]$/',$value)===1; }
function accClient(PDO $pdo, array $ctx, string $id, string $uid, bool $manager): array {
