    if (!$manager) $sql .= ' AND (c.created_by = ? OR EXISTS (SELECT 1 FROM client_members cm WHERE cm.client_id = c.id AND cm.user_id = ?))';
    $q = $pdo->prepare($sql); $q->execute(array_merge([$id], $ids, $manager ? [] : [$uid, $uid])); $row = $q->fetch();
