    $internalDue = (string)($obligation['internal_due'] ?? '');
    $today = (new DateTimeImmutable('today', new DateTimeZone('Europe/Kyiv')))->format('Y-m-d');
    if (!accValidDate($internalDue) || $internalDue < $today) return;
    $assigneeQuery = $pdo->prepare('SELECT user_id FROM accounting_obligation_assignees WHERE owner_id=? AND obligation_id=? ORDER BY user_id');
    $assigneeQuery->execute([$ownerId, (string)$obligation['id']]);
    $assignees = array_map('strval', $assigneeQuery->fetchAll(PDO::FETCH_COLUMN));
    if (!$assignees) return;
    $taskId = (string)($obligation['task_id'] ?? '');
    $dueAt = $internalDue . ' 09:00:00';
    $title = mb_substr('Податковий дедлайн · ' . (string)$obligation['title'], 0, 180);
    $description = 'Податкове зобов’язання для клієнта «' . (string)$client['name'] . '». Внутрішній дедлайн: ' . $internalDue . '. Офіційний строк: ' . (string)$obligation['official_due'] . '.';
    if ($taskId === '') {
        $taskId = accId();
        $pdo->prepare('INSERT INTO tasks(id,title,description,client_name,assignee_id,created_by,status,priority,due_date,reminder_at,creator_reminder,recurrence_rule) VALUES(?,?,?,?,?,?,\'todo\',\'high\',?,?,1,\'none\')')->execute([$taskId,$title,$description,mb_substr((string)$client['name'],0,180),$assignees[0],$userId,$dueAt,$dueAt]);
        $pdo->prepare('UPDATE accounting_obligations SET task_id=? WHERE id=? AND owner_id=?')->execute([$taskId,(string)$obligation['id'],$ownerId]);
        $pdo->prepare("INSERT INTO task_history(id,task_id,user_id,action,message) VALUES(?,?,?,'created','Створено автоматично за внутрішнім дедлайном податкового зобов’язання.')")->execute([accId(),$taskId,$userId]);
    } else {
        $pdo->prepare("UPDATE tasks SET title=?,description=?,client_name=?,assignee_id=?,due_date=?,reminder_at=? WHERE id=? AND status NOT IN ('done','cancelled','archived')")->execute([$title,$description,mb_substr((string)$client['name'],0,180),$assignees[0],$dueAt,$dueAt,$taskId]);
    }
    $pdo->prepare('INSERT IGNORE INTO task_clients(task_id,client_id) VALUES(?,?)')->execute([$taskId,(string)$obligation['client_id']]);
    $pdo->prepare('DELETE FROM task_assignees WHERE task_id=?')->execute([$taskId]);
    $insertAssignee = $pdo->prepare('INSERT IGNORE INTO task_assignees(task_id,user_id) VALUES(?,?)');
    foreach ($assignees as $assigneeId) $insertAssignee->execute([$taskId,$assigneeId]);
}
function accMatches(array $criteria, array $c): bool { $s=accSnapshot($c); foreach($criteria as $key=>$value) { if ($value === '' || $value === null || $value === []) continue; $actual = $key === 'tax_group' ? ($s['tax_group'] ?: $s['tax_system']) : ($s[$key] ?? null); if (is_array($value) ? !in_array($actual,$value,true) : (string)$actual !== (string)$value) return false; } return true; }
function accVchasnoGroup(array $client): ?int {
    $system = mb_strtolower(trim((string)($client['tax_system'] ?? '')));
    $group = mb_strtolower(trim((string)($client['module_data']['tax_group'] ?? '')));
    $value = $group !== '' ? $group : $system;
    if ($value === '1') return 1;
    if ($value === '2') return 2;
    if ($value === '3') return !empty($client['has_vat']) ? 4 : 3;
    if (preg_match('/(?:^|\s)1 група/u', $value)) return 1;
    if (preg_match('/(?:^|\s)2 група/u', $value)) return 2;
    if (preg_match('/(?:^|\s)3 група/u', $value) || str_contains($value, 'єдиний податок, 3')) return !empty($client['has_vat']) ? 4 : 3;
    if (str_contains($value, 'загальна')) return !empty($client['has_vat']) ? 6 : 5;
    return null;
}
